mapper.select:
/* selectMasterMdctBuyerIrsnManageList */ SELECT K.SITE ,K.COM_CODE ,K.COM_CODE AS COM_CODE_TEXT ,(SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = K.COM_CODE) AS COM_NAME ,K.IRS_NO ,K.IRS_NO AS AS_IS_IRS_NO ,K.IRS_NAME ,K.CEO_NAME_LOC ,K.INDUSTRY_TYPE ,K.BUSINESS_ITEMS ,K.ZIP_CODE ,K.ADDRESS_LOC ,K.CHANGE_DATE ,K.CHANGE_TIME ,K.CHANGE_USER_ID ,(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = K.CHANGE_USER_ID) AS CHANGE_USER_NM ,K.SAP_CODE ,'1' AS MAP_COM_CODE_TEXT ,K.COMPANY AS MAP_COM_CODE ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = K.COMPANY) AS MAP_COM_NAME FROM KEPTIRSN K WHERE 1=1
AND K.SITE = #{st_kep_site}
AND K.IRS_NO = #{st_irs_no}
AND K.SAP_CODE = #{st_sap_code}
AND K.IRS_NAME LIKE '%' || #{st_irs_name} || '%'
AND K.CEO_NAME_LOC LIKE '%' || #{st_ceo_name} || '%'
AND (SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = K.COM_CODE) LIKE '%' || #{st_com_name} || '%'


/* getMasterMdctBuyerIrsnManageIrsNoCheck */
SELECT
	COUNT(IRS_NO) CNT
FROM KEPTIRSN
WHERE SITE				= #{SITE}
AND COM_CODE		= #{COM_CODE}
AND IRS_NO				= #{IRS_NO}

mapper.update:

/* updateMasterMdctBuyerIrsnManageList */
UPDATE KEPTIRSN					
SET  COMPANY = #{MAP_COM_CODE}
	, IRS_NAME			= #{IRS_NAME} 	
	,CEO_NAME_LOC	= #{CEO_NAME_LOC}
	,INDUSTRY_TYPE		= #{INDUSTRY_TYPE}
	,BUSINESS_ITEMS	= #{BUSINESS_ITEMS}
	,ZIP_CODE			= #{ZIP_CODE}
	,ADDRESS_LOC		= #{ADDRESS_LOC}
	,CHANGE_DATE		= TO_CHAR(SYSDATE, 'YYYYMMDD')
	,CHANGE_TIME		= TO_CHAR(SYSDATE, 'HH24MISS')
	,CHANGE_USER_ID	= #{st_user_id}
WHERE SITE				= #{SITE}
AND COM_CODE		= #{COM_CODE}
AND IRS_NO				= #{IRS_NO}


/* insertMasterMdctBuyerIrsnManageList */
INSERT INTO KEPTIRSN
(
	SITE
	,COM_CODE
	,IRS_NO
	,IRS_NAME
	,CEO_NAME_LOC
	,INDUSTRY_TYPE
	,BUSINESS_ITEMS
	,ZIP_CODE
	,ADDRESS_LOC
	,CHANGE_DATE
	,CHANGE_TIME
	,CHANGE_USER_ID
	,COMPANY
) VALUES (
	#{SITE}
	,#{COM_CODE}
	,#{IRS_NO}
	,#{IRS_NAME}
	,#{CEO_NAME_LOC}
	,#{INDUSTRY_TYPE}
	,#{BUSINESS_ITEMS}
	,#{ZIP_CODE}
	,#{ADDRESS_LOC}
	,TO_CHAR(SYSDATE, 'YYYYMMDD')
	,TO_CHAR(SYSDATE, 'HH24MISS')
	,#{st_user_id}
	,#{MAP_COM_CODE}
)


/* deletetMasterMdctBuyerIrsnManageList */
DELETE FROM KEPTIRSN
WHERE SITE					= #{SITE}
AND COM_CODE			= #{COM_CODE}
AND IRS_NO					= #{IRS_NO}
